//! 🧪️ Finite lower recipient loans retain independent effects and refusals.
use super::*;
use crate::native_encoding::{NativeEncodeAllocationEvent,NativeEncodeConstructionRecipient,NativeEncodeWorkRecipient,NativeEncodeAllocationIssuer,NativeEncodeWorkIssuer,NativeEncodeConstructionIssuer};
use crate::retirement::{RetireOwned,controlled::ControlledRetirement};
use crate::ErasedSnapshotRetirement;
fn error(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::Canceled,message)}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:128,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:16}}
struct Work{posted:u64}
impl NativeEncodeWorkRecipient for Work{fn admits(&mut self,_:u64,_:u64)->Result<bool,ValueError>{Ok(true)}fn committed(&mut self,actual:u64)->Result<(),ValueError>{self.posted+=actual;Err(error("work post"))}}
struct AcceptWork{posted:u64}
impl NativeEncodeWorkRecipient for AcceptWork{fn admits(&mut self,_:u64,_:u64)->Result<bool,ValueError>{Ok(true)}fn committed(&mut self,actual:u64)->Result<(),ValueError>{self.posted+=actual;Ok(())}}
struct Physical{submitted:RetainedCloneProgress}
impl NativeEncodeConstructionRecipient for Physical{fn submitted(&self)->RetainedCloneProgress{self.submitted}fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(grant())}fn accept(&mut self,_:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{self.submitted=self.submitted.checked_add(progress)?;Err(error("physical post"))}}
fn close<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::retain(value);for _ in 0..65536{if owner.terminal_is_empty(){return}owner.step(grant()).unwrap();}panic!("finite lower fixture did not close")}
#[test]
fn real_backing_retains_every_independent_refusal(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️.json")).unwrap();assert_eq!(fixture[3]["expectedCauses"],4);let mut observer=|_|true;let mut port=|event|match event{NativeEncodeAllocationEvent::Post{..}=>Err(error("allocation post")),_=>Ok(())};let mut legacy_work=|_,_|Ok(());let mut allocation_loan_issuer=crate::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.scoped_loan(&mut port);let mut native=NativeEncodeControl::new_scoped_source(8,16,&mut observer,&mut allocation_loan,&mut legacy_work);let mut payer=Work{posted:0};let mut physical=Physical{submitted:Default::default()};let mut local=RetainedCloneProgress::default();let mut state=NativeEncodeEffectState::default();assert_eq!(state.allocation_status(),NativeEncodeAllocationOutcomeStatus::Absent);let mut unwind=None;let mut output=None;let header=std::mem::size_of::<Vec<u8>>();let demand=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header,maximum_capacity_bytes:8,maximum_depth:1,..Default::default()};let mut result=None;
 let mut work_issuer=NativeEncodeWorkIssuer::new();let mut physical_issuer=NativeEncodeConstructionIssuer::new();let mut work_loan=work_issuer.loan(&mut payer);let mut physical_loan=physical_issuer.loan(&mut physical);native.with_work_recipient(&mut work_loan,|native|native.with_construction_recipient(&mut physical_loan,|native|{let turn=native.effect_allocated(grant(),&mut local,demand,Some(8),&mut state.view(),&mut unwind,&mut |performed,progress,actual|{*performed=true;let mut bytes=Vec::<u8>::new();bytes.try_reserve_exact(8).map_err(|_|error("allocator refused"))?;let capacity=bytes.capacity();output=Some(bytes);*actual=Some(capacity);*progress=RetainedCloneProgress{copied_items:1,copied_bytes:header,retained_capacity_bytes:capacity,..Default::default()};Err(error("operation"))});assert_eq!(turn.work,1);result=Some(turn.result.err().unwrap());Ok::<(),ValueError>(())})).unwrap();drop(work_loan);drop(physical_loan);
 let failure=result.take().unwrap();assert_eq!(payer.posted,1);assert_eq!(physical.submitted,local);assert!(failure.work.is_some());assert!(failure.physical.is_some());assert_eq!(native_encode_allocation_outcome_status(&failure.allocation),NativeEncodeAllocationOutcomeStatus::Refused);let allocation=failure.allocation.as_ref().unwrap();assert!(allocation.primary.is_some());assert!(allocation.scoped_refusal.is_some());assert!(failure.local.is_none());assert!(failure.invariant.is_none());assert!(failure.physical_invariant.is_none());assert!(failure.capacity_invariant.is_none());assert!(unwind.is_none());close(failure);close(output.take().unwrap());close(state);
}

#[test]
fn denied_and_unperformed_effects_do_not_post_work(){
 for denied in [true,false]{let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut legacy_work=|_,_|Ok(());let mut allocation_loan_issuer=crate::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.scoped_loan(&mut port);let mut native=NativeEncodeControl::new_scoped_source(8,16,&mut observer,&mut allocation_loan,&mut legacy_work);let mut payer=Work{posted:0};let mut physical=Physical{submitted:Default::default()};let mut local=RetainedCloneProgress::default();let mut state=NativeEncodeEffectState::default();let mut unwind=None;let mut called=false;let mut failure=None;let demand=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let original=if denied{RetainedCloneGrant{maximum_items:0,..grant()}}else{grant()};
 let mut work_issuer=NativeEncodeWorkIssuer::new();let mut physical_issuer=NativeEncodeConstructionIssuer::new();let mut work_loan=work_issuer.loan(&mut payer);let mut physical_loan=physical_issuer.loan(&mut physical);native.with_work_recipient(&mut work_loan,|native|native.with_construction_recipient(&mut physical_loan,|native|{let turn=native.effect_allocated(original,&mut local,demand,None,&mut state.view(),&mut unwind,&mut |_,_,_|{called=true;Ok(())});assert_eq!(turn.work,0);failure=turn.result.err();Ok::<(),ValueError>(())})).unwrap();drop(work_loan);drop(physical_loan);assert_eq!(called,!denied);assert_eq!(failure.is_some(),denied);assert_eq!(payer.posted,0);assert_eq!(physical.submitted,RetainedCloneProgress::default());assert_eq!(local,RetainedCloneProgress::default());assert!(unwind.is_none());if let Some(failure)=failure{close(failure)}close(state);}
}

#[test]
fn scoped_continuation_preserves_original_issuer_and_recipient(){
 use crate::native_encoding::NativeEncodeRetirementRecipient;let mut issuer=NativeEncodeAllocationIssuer::new();let mut other_issuer=NativeEncodeAllocationIssuer::new();let mut recipient=NativeEncodeRetirementRecipient::new();let mut other_recipient=NativeEncodeRetirementRecipient::new();
 let receipt={let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let mut control=NativeEncodeControl::new_scoped_source(8,16,&mut observer,&mut loan,&mut work);control.install_retirement_recipient(&mut recipient).unwrap();let mut actual=None;let mut pending=None;let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.allocate_effect(8,&mut actual,&mut pending,&mut |_|panic!("unperformed allocation unwind"))));assert!(panic.is_err());let(error,mut control)=match control.pause_scoped_source(&pending){Err(value)=>value,Ok(_)=>panic!("pending allocation cannot detach")};close(error);assert!(pending.as_ref().unwrap().pending());control.settle_allocation_progress(pending.as_mut().unwrap(),None).unwrap();close(pending.take().unwrap());match control.pause_scoped_source(&pending){Ok(receipt)=>receipt,Err(_)=>panic!("settled original source should detach")}};
 let receipt={let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut loan=other_issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());match NativeEncodeControl::resume_scoped_source(receipt,8,16,&mut observer,&mut loan,&mut work,&mut recipient){Err((receipt,error))=>{close(error);receipt},Ok(_)=>panic!("different issuer cannot rebind")}};
 let receipt={let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());match NativeEncodeControl::resume_scoped_source(receipt,8,16,&mut observer,&mut loan,&mut work,&mut other_recipient){Err((receipt,error))=>{close(error);receipt},Ok(_)=>panic!("different recipient cannot rebind")}};
 let receipt={let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let control=match NativeEncodeControl::resume_scoped_source(receipt,8,16,&mut observer,&mut loan,&mut work,&mut recipient){Ok(control)=>control,Err(_)=>panic!("original Source identities must rebind")};match control.pause_scoped_source(&None){Ok(receipt)=>receipt,Err(_)=>panic!("rebound Source should detach")}};close(receipt);
}

#[test]
fn zero_backing_does_not_invent_an_allocation_event(){
 let mut observer=|_|true;let mut native=NativeEncodeControl::new(0,&mut observer);let mut local=RetainedCloneProgress::default();let mut state=NativeEncodeEffectState::default();let mut unwind=None;let turn=native.effect_allocated(grant(),&mut local,RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()},Some(0),&mut state.view(),&mut unwind,&mut |_,_,_|panic!("zero backing must not execute"));assert_eq!(turn.work,0);assert_eq!(local,RetainedCloneProgress::default());assert!(unwind.is_none());close(turn.result.err().unwrap());close(state);
}

#[test]
fn borrowed_status_keeps_original_settlement_refusals_in_place(){
 let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut allocation_issuer=NativeEncodeAllocationIssuer::new();let mut loan=allocation_issuer.scoped_loan(&mut port);let mut legacy_work=|_,_|Ok(());let mut native=NativeEncodeControl::new_scoped_source(0,16,&mut observer,&mut loan,&mut legacy_work);let mut payer=Work{posted:0};let mut physical=Physical{submitted:Default::default()};let mut work_issuer=NativeEncodeWorkIssuer::new();let mut physical_issuer=NativeEncodeConstructionIssuer::new();let mut work_loan=work_issuer.loan(&mut payer);let mut physical_loan=physical_issuer.loan(&mut physical);let mut state=NativeEncodeEffectState::default();let mut value=0u8;assert_eq!(state.settlement_status(),NativeEncodeEffectSettlementStatus::Absent);
 native.with_work_recipient(&mut work_loan,|native|native.with_construction_recipient(&mut physical_loan,|native|{native.begin_effect_settlement(&mut state.settlement,RetirementDemand{copy_bytes:1,depth:1,..Default::default()})?;assert_eq!(state.view().settlement_status(),NativeEncodeEffectSettlementStatus::Pending);value=1;state.settlement.as_mut().unwrap().record_effect(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()})?;native.settle_effect(&mut state.settlement)?;Ok::<(),ValueError>(())})).unwrap();drop(work_loan);drop(physical_loan);assert_eq!(value,1);assert_eq!(state.settlement_status(),NativeEncodeEffectSettlementStatus::Refused);let(work,physical,invariant)=state.settlement.as_ref().unwrap().failures();assert!(work.is_some());assert!(physical.is_some());assert!(invariant.is_none());close(state);
}

#[test]
fn native_encode_depth_restores_the_original_scope_after_unwind(){
 let mut observer=|_|true;let mut native=NativeEncodeControl::new(0,&mut observer);let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.scoped_depth(1,|_|->Result<(),ValueError>{panic!("fixture nested unwind")})));assert!(panic.is_err());let mut entered=false;native.scoped_depth(1,|_|{entered=true;Ok::<(),ValueError>(())}).unwrap();assert!(entered);
}

#[test]
fn scoped_encoder_retains_actual_overage_without_minting_a_new_grant(){
 use crate::native_encoding::NativeEncodeRetirementRecipient;let mut issuer=NativeEncodeAllocationIssuer::new();let mut recipient=NativeEncodeRetirementRecipient::new();let mut output=None;let mut actual=None;let mut pending=None;let mut allocation=None;
 let receipt={let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let mut native=NativeEncodeControl::new_scoped_source(8,16,&mut observer,&mut loan,&mut work);native.install_retirement_recipient(&mut recipient).unwrap();let mut payer=AcceptWork{posted:0};let mut work_issuer=NativeEncodeWorkIssuer::new();let mut work_loan=work_issuer.loan(&mut payer);native.with_work_recipient(&mut work_loan,|native|{assert!(native.prepare_work(1)?);allocation=Some(native.allocate_effect(8,&mut actual,&mut pending,&mut |actual|{let mut bytes=Vec::<u8>::new();bytes.try_reserve_exact(16).map_err(|_|error("allocator refused"))?;*actual=Some(bytes.capacity());output=Some(bytes);Ok(())}));native.commit_work(1)?;Ok::<(),ValueError>(())}).unwrap();drop(work_loan);assert_eq!(payer.posted,1);assert_eq!(native.owned_bytes(),16);match native.pause_scoped_source(&pending){Ok(receipt)=>receipt,Err(_)=>panic!("actual overage must remain detachable")}};
 let allocation=allocation.take().unwrap();assert!(allocation.extent_refusal.is_some());assert_eq!(receipt.owned_bytes(),16);close(allocation);
 let receipt={let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let mut native=match NativeEncodeControl::resume_scoped_source(receipt,0,16,&mut observer,&mut loan,&mut work,&mut recipient){Ok(native)=>native,Err(_)=>panic!("overage receipt must rebind")};assert_eq!(native.owned_bytes(),16);assert_eq!(native.maximum_bytes(),16);let mut actual=None;let mut pending=None;let denied=native.allocate_effect(1,&mut actual,&mut pending,&mut |_|panic!("unfunded allocation cannot run"));assert!(denied.primary.is_some());close(denied);match native.pause_scoped_source(&pending){Ok(receipt)=>receipt,Err(_)=>panic!("denied extra allocation must preserve receipt")}};
 let receipt={let mut observer=|_|true;let mut port=|_:NativeEncodeAllocationEvent|Ok(());let mut loan=issuer.scoped_loan(&mut port);let mut work=|_,_|Ok(());let native=match NativeEncodeControl::resume_scoped_source(receipt,3,16,&mut observer,&mut loan,&mut work,&mut recipient){Ok(native)=>native,Err(_)=>panic!("real additional grant must rebind")};assert_eq!(native.owned_bytes(),16);assert_eq!(native.maximum_bytes(),19);match native.pause_scoped_source(&None){Ok(receipt)=>receipt,Err(_)=>panic!("Source receipt must detach")}};close(receipt);close(output.take().unwrap());
}
